import re


def tokenize(sentence):
    """Split a sentence into words, dropping surrounding punctuation."""
    if not isinstance(sentence, str):
        raise TypeError("sentence must be a string")
    raw = re.split(r"\s+", sentence.strip())
    words = []
    for chunk in raw:
        cleaned = chunk.strip(".,;:!?\"'()[]{}")
        if cleaned:
            words.append(cleaned)
    return words


def find_longest_word(sentence):
    """Return the first longest word of the sentence, or '' if there is none."""
    longest = ""
    best = 0
    for word in tokenize(sentence):
        size = len(word)
        if size > best:
            best = size
            longest = word
    return longest


def length_histogram(sentence):
    """Map each word length to the number of words having it."""
    counts = {}
    for word in tokenize(sentence):
        key = len(word)
        counts.setdefault(key, 0)
        counts[key] += 1
    return counts


def average_word_length(sentence):
    """Return the mean word length, or 0.0 for a sentence without words."""
    words = tokenize(sentence)
    if not words:
        return 0.0
    total = 0
    for word in words:
        total += len(word)
    return total / len(words)


def describe(sentence):
    """Build a short human readable report about the sentence."""
    longest = find_longest_word(sentence)
    words = tokenize(sentence)
    target = len(longest)
    ties = []
    for word in words:
        if len(word) == target:
            ties.append(word)
    lines = []
    lines.append("sentence: " + repr(sentence))
    lines.append("words: {}".format(len(words)))
    lines.append("longest: {!r} ({} letters)".format(longest, target))
    if len(ties) > 1:
        lines.append("tied with: " + ", ".join(repr(w) for w in ties[1:]))
    lines.append("average length: {:.2f}".format(average_word_length(sentence)))
    histogram = length_histogram(sentence)
    for size in sorted(histogram):
        lines.append("  {:2d} words of this length: {}".format(size, histogram[size]))
    return "\n".join(lines)


def main():
    samples = [
        "The quick brown fox",
        "Hello world",
        "Nothing beats a well-placed semicolon; really, nothing does.",
        "   ",
    ]
    for sample in samples:
        print(describe(sample))
        print("-" * 40)


if __name__ == "__main__":
    main()

