def validate_operations(operations):
    """Check that each entry is a supported (action, payload) pair."""
    if not isinstance(operations, (list, tuple)):
        raise TypeError("operations must be a list of tuples")
    cleaned = []
    for index, entry in enumerate(operations):
        if len(entry) != 2:
            raise ValueError("operation {} must have exactly two fields".format(index))
        action, payload = entry
        action = str(action).strip().lower()
        if action == "dequeue":
            if payload is None:
                cleaned.append((action, None))
            else:
                raise ValueError("dequeue takes no payload at position {}".format(index))
        elif action == "enqueue":
            cleaned.append((action, payload))
        else:
            raise ValueError("unknown action {!r} at position {}".format(action, index))
    return cleaned


def simulate_queue(operations):
    """Run the operations against a list-backed queue and return its final state."""
    queue = []
    for action, payload in validate_operations(operations):
        if action == "enqueue":
            queue.append(payload)
        elif queue:
            queue.pop(0)
    return queue


def trace_queue(operations):
    """Return a note and a queue snapshot for every operation."""
    queue = []
    history = []
    for action, payload in validate_operations(operations):
        if action == "enqueue":
            queue.append(payload)
            note = "pushed {!r}".format(payload)
        elif queue:
            removed = queue.pop(0)
            note = "popped {!r}".format(removed)
        else:
            note = "ignored dequeue on empty queue"
        history.append((note, list(queue)))
    return history


def format_trace(operations):
    """Build a human readable report of the simulation."""
    history = trace_queue(operations)
    width = len(str(len(history)))
    lines = []
    step = 0
    for note, snapshot in history:
        step += 1
        label = str(step).rjust(width)
        lines.append("{}. {} | {}".format(label, note.ljust(34), snapshot))
    final = simulate_queue(operations)
    summary = "{} operation(s), {} item(s) remaining"
    lines.append(summary.format(len(history), len(final)))
    return "\n".join(lines)


def main():
    samples = [
        [("enqueue", 1), ("enqueue", 2), ("dequeue", None)],
        [("dequeue", None)],
        [("enqueue", "a"), ("dequeue", None), ("enqueue", "b"), ("enqueue", "c")],
    ]
    number = 0
    for ops in samples:
        number += 1
        print("sample {}".format(number))
        print(format_trace(ops))
        print("final: {!r}".format(simulate_queue(ops)))
        print()


if __name__ == "__main__":
    main()

