def check_stock(inventory, items_to_check):
    """Return a mapping of each requested item to its available quantity."""
    stock_levels = {}
    for item in items_to_check:
        quantity = inventory.get(item, 0)
        if quantity < 0:
            quantity = 0
        stock_levels[item] = quantity
    return stock_levels


def normalize_inventory(raw_inventory):
    """Clean up an inventory: trim names, merge duplicates, drop bad counts."""
    grouped = {}
    for name, quantity in raw_inventory.items():
        key = str(name).strip().lower()
        if not key:
            continue
        if not isinstance(quantity, int):
            continue
        grouped.setdefault(key, [])
        grouped[key].append(quantity)
    cleaned = {}
    for key, quantities in grouped.items():
        cleaned[key] = sum(quantities)
    return cleaned


def find_shortages(stock_levels, threshold):
    """List items whose stock is at or below the given threshold."""
    shortages = []
    for item, quantity in sorted(stock_levels.items()):
        if quantity <= threshold:
            shortages.append(item)
    return shortages


def units_needed(quantity, target):
    """Units required to bring a single item up to the target level."""
    if quantity >= target:
        return 0
    return target - quantity


def restock_plan(stock_levels, target):
    """How many units of each item must be ordered to reach the target level."""
    plan = {}
    for item, quantity in stock_levels.items():
        needed = units_needed(quantity, target)
        if needed > 0:
            plan[item] = needed
    return plan


def format_report(stock_levels, threshold, target):
    """Build a human readable stock report as a list of text lines."""
    lines = []
    low_items = find_shortages(stock_levels, threshold)
    for item, quantity in sorted(stock_levels.items()):
        marker = "OK"
        if item in low_items:
            marker = "LOW"
        label = item.ljust(10)
        count = str(quantity).rjust(4)
        lines.append("{} {}  {}".format(label, count, marker))
    lines.append("-" * 20)
    total_units = sum(stock_levels.values())
    lines.append("total units: {}".format(total_units))
    plan = restock_plan(stock_levels, target)
    for item in sorted(plan):
        lines.append("order {} x {}".format(plan[item], item))
    return lines


def main():
    raw_inventory = {
        " Apple ": 10,
        "apple": 2,
        "banana": 5,
        "milk": "many",
        "bread": 1,
    }
    inventory = normalize_inventory(raw_inventory)
    items_to_check = ["apple", "orange", "milk", "bread"]
    stock_levels = check_stock(inventory, items_to_check)
    print(stock_levels)
    for line in format_report(stock_levels, 1, 6):
        print(line)
    shortages = find_shortages(stock_levels, 1)
    print("shortages: " + ", ".join(shortages))


if __name__ == "__main__":
    main()

