import itertools
import random

HEADS = 'Heads'
TAILS = 'Tails'


def simulate_coin_flip():
    """Flip a fair coin once and return 'Heads' or 'Tails'."""
    toss = random.random()
    if toss < 0.5:
        result = HEADS
    else:
        result = TAILS
    return result


def flip_many(count):
    """Flip the coin `count` times and return the list of outcomes."""
    if count < 0:
        raise ValueError('count must not be negative')
    return [simulate_coin_flip() for _ in range(count)]


def tally(flips):
    """Count how often each face came up."""
    counts = {face: flips.count(face) for face in (HEADS, TAILS)}
    return counts


def longest_streak(flips):
    """Return the length of the longest run of identical outcomes."""
    runs = [len(list(group)) for _, group in itertools.groupby(flips)]
    if not runs:
        return 0
    return max(runs)


def ratio(part, whole):
    """Return `part` divided by `whole`, or 0.0 when `whole` is empty."""
    if whole <= 0:
        return 0.0
    return part / whole


def percentage(part, whole):
    """Return `part` as a percentage of `whole`."""
    return 100.0 * ratio(part, whole)


def format_report(flips):
    """Build a human readable summary of a sequence of flips."""
    counts = tally(flips)
    total = len(flips)
    lines = ['Flips: {}'.format(total)]
    for face in (HEADS, TAILS):
        hits = counts[face]
        share = percentage(hits, total)
        lines.append('{}: {} ({:.1f}%)'.format(face, hits, share))
    streak = longest_streak(flips)
    lines.append('Longest streak: {}'.format(streak))
    return '\n'.join(lines)


