    for index, (nested, sep) in enumerate(samples, 1):
        header = "sample {0} separator={1}".format(index, repr(sep))
        print(header)
        print(flatten_dict(nested, sep))
        print(format_report(nested, sep))
        print("-" * 32)


if __name__ == "__main__":
