def validate_trade(buy_price, sell_price, quantity):
    """Check that a trade's inputs describe a real position."""
    if buy_price <= 0:
        raise ValueError("buy_price must be positive")
    if sell_price < 0:
        raise ValueError("sell_price cannot be negative")
    if quantity <= 0:
        raise ValueError("quantity must be a positive number of shares")
    if quantity != int(quantity):
        raise ValueError("quantity must be a whole number of shares")


def per_share_gain(buy_price, sell_price):
    """Gain (or loss) realised on a single share."""
    return sell_price - buy_price


def calculate_stock_profit(buy_price, sell_price, quantity):
    """Return the profit (positive) or loss (negative) of one transaction."""
    validate_trade(buy_price, sell_price, quantity)
    per_share = per_share_gain(buy_price, sell_price)
    return round(per_share * quantity, 2)


def relative_gain(buy_price, sell_price):
    """Gain per unit of capital invested in a share."""
    return per_share_gain(buy_price, sell_price) / buy_price


def return_percentage(buy_price, sell_price):
    """Percentage change between the buy and the sell price."""
    fraction = relative_gain(buy_price, sell_price)
    return round(100.0 * fraction, 2)


def per_share_fee(fee, quantity):
    """Part of a flat commission carried by each share of the position."""
    return fee / quantity


def break_even_price(buy_price, quantity, fee):
    """Sell price per share needed to cover the purchase plus a flat fee."""
    fee_share = per_share_fee(fee, quantity)
    return round(buy_price + fee_share, 4)


def describe_trade(symbol, buy_price, sell_price, quantity):
    """Build a one-line human readable summary of a trade."""
    profit_loss = calculate_stock_profit(buy_price, sell_price, quantity)
    pct = return_percentage(buy_price, sell_price)
    if profit_loss > 0:
        verdict = "profit"
    elif profit_loss < 0:
        verdict = "loss"
    else:
        verdict = "break-even"
    return "{:<6}{:>5} sh  {:>8.2f} -> {:>8.2f}  {:>10.2f} ({:+.2f}%) {}".format(
        symbol, quantity, buy_price, sell_price, abs(profit_loss), pct, verdict
    )


def portfolio_summary(trades):
    """Total the profit/loss of many trades and count winners and losers."""
    total = 0.0
    winners = 0
    losers = 0
    for trade in trades:
        result = calculate_stock_profit(trade[1], trade[2], trade[3])
        total += result
        if result > 0:
            winners += 1
        elif result < 0:
            losers += 1
    return round(total, 2), winners, losers


def main():
    trades = [
        ("AAPL", 10.0, 12.0, 100),
        ("MSFT", 15.0, 13.0, 50),
        ("TSLA", 220.5, 248.75, 12),
        ("KO", 60.0, 60.0, 30),
    ]
    for symbol, buy_price, sell_price, quantity in trades:
        print(describe_trade(symbol, buy_price, sell_price, quantity))

    total, winners, losers = portfolio_summary(trades)
    print("-" * 60)
    print("Net result: {:.2f} across {} trades".format(total, len(trades)))
    print("Winners: {}   Losers: {}".format(winners, losers))

    fee = 9.95
    target = break_even_price(220.5, 12, fee)
    print("TSLA break-even with {:.2f} fee: {:.4f}".format(fee, target))


if __name__ == "__main__":
    main()

