def find_duplicate(numbers):
    n = len(numbers) - 1
    expected_sum = n * (n + 1) / 2
    actual_sum = 0
    for num in numbers:
        actual_sum = actual_sum + num
    duplicate_num = int(actual_sum - expected_sum)
    if duplicate_num < 0:
        duplicate_num = 0 - duplicate_num
    return duplicate_num

