def added_keys(dict1, dict2):
    """Keys that the merge introduces from dict2."""
    fresh=[]
    for key in dict2:
        if key not in dict1:
            fresh.append(key)
    return fresh


def kept_count(dict1, dict2):
    """Number of dict1 entries that survive the merge unchanged."""
    return len(dict1)-len(overridden_keys(dict1, dict2))


def format_dict(mapping):
    """Format a dict with keys in sorted order for stable output."""
    parts=[]
    for key in sorted(mapping, key=str):
        parts.append("{!r}: {!r}".format(key, mapping[key]))
    body=", ".join(parts)
    return "{{{}}}".format(body)


def describe_merge(dict1, dict2):
    """Build a short human readable report about a merge."""
    merged=merge_dicts(dict1, dict2)
    added=added_keys(dict1, dict2)
    changed=overridden_keys(dict1, dict2)
    lines=[]
    lines.append("result: "+format_dict(merged))
    lines.append("size: "+str(len(merged)))
    if added:
        lines.append("added: "+", ".join(sorted(map(str, added))))
    if changed:
        lines.append("overwritten: "+", ".join(sorted(map(str, changed))))
    return "\n".join(lines)


def main():
    first={'a': 1, 'b': 2}
    second={'b': 3, 'c': 4}
    print(describe_merge(first, second))
    print(format_dict(merge_dicts({'x': 10}, {'y': 20})))

    defaults={'host': 'localhost', 'port': 8080, 'debug': False}
    user_config={'port': 9000, 'debug': True}
    env_config={'host': '0.0.0.0'}
    settings=merge_all([defaults, user_config, env_config])
    print(format_dict(settings))

    kept=kept_count(defaults, user_config)
    print("defaults kept after user config: "+str(kept))


if __name__=="__main__":
    main()

