def find_common_elements(list1, list2):
    """Return the elements that appear in both list1 and list2."""
    if not isinstance(list1, list):
        raise TypeError("list1 must be a list")
    if not isinstance(list2, list):
        raise TypeError("list2 must be a list")
    lookup = set(list2)
    common = []
    for item in dict.fromkeys(list1):
        if item in lookup:
            common.append(item)
    return common


def union_size(list1, list2):
    """Count the distinct values found across both lists."""
    distinct = set(list1)
    distinct.update(list2)
    return len(distinct)


def overlap_ratio(list1, list2):
    """Fraction of the distinct values that the two lists share."""
    total = union_size(list1, list2)
    if total == 0:
        return 0.0
    shared = len(find_common_elements(list1, list2))
    return shared / total


def exclusive_elements(list1, list2):
    """Values present in exactly one of the two lists."""
    shared = set(find_common_elements(list1, list2))
    only_first = []
    only_second = []
    for item in dict.fromkeys(list1):
        if item not in shared:
            only_first.append(item)
    for item in dict.fromkeys(list2):
        if item not in shared:
            only_second.append(item)
    return only_first, only_second


def format_percent(ratio):
    """Render a ratio as a percentage string with one decimal."""
    return "{0:.1%}".format(ratio)


def format_report(list1, list2):
    """Build a short human readable summary of the comparison."""
    common = find_common_elements(list1, list2)
    only_first, only_second = exclusive_elements(list1, list2)
    ratio = overlap_ratio(list1, list2)
    lines = []
    lines.append("first list:  " + repr(list1))
    lines.append("second list: " + repr(list2))
    lines.append("common:      " + repr(common))
    lines.append("count:       " + str(len(common)))
    lines.append("only first:  " + repr(only_first))
    lines.append("only second: " + repr(only_second))
    lines.append("overlap:     " + format_percent(ratio))
    return "\n".join(lines)


def main():
    pairs = [
        ([1, 2, 3, 4], [3, 4, 5, 6]),
        (['a', 'b'], ['c', 'd']),
        ([1, 1, 2, 2, 3], [2, 3, 3, 9]),
        ([], [7, 8]),
    ]
    for index, (first, second) in enumerate(pairs, 1):
        print("Comparison #{0}".format(index))
        print(format_report(first, second))
        print("-" * 30)


if __name__ == "__main__":
    main()

