def is_valid_luhn(card_number):
    total = 0
    num_digits = len(card_number)
    is_second = False

    for i in range(num_digits - 1, -1, -1):
        digit = int(card_number[i])

        if is_second:
            digit *= 2
            if digit > 9:
                digit -= 9

        total += digit
        is_second = not is_second

    return total % 10 == 0

