def fibonacci_sequence(n: int) -> list[int]:
    if n <= 0:
        return []
    elif n == 1:
        return [0]

    fib_list = [0, 1]
    a, b = 0, 1

    while True:
        next_fib = a + b
        if next_fib >= n:
            break
        fib_list.append(next_fib)
        a = b
        b = next_fib

    return fib_list

