def _positive(value, label):
    """Convert a measurement to float and reject non-positive numbers."""
    number = float(value)
    if number <= 0:
        raise ValueError("{} must be positive".format(label))
    return number


def _area(height_m):
    """Return the squared height used by the BMI formula."""
    return height_m * height_m


def calculate_bmi(weight_kg, height_m):
    """Return the BMI for a weight in kilograms and a height in meters."""
    weight = _positive(weight_kg, "weight_kg")
    height = _positive(height_m, "height_m")
    return round(weight / _area(height), 2)


def classify_bmi(bmi):
    """Map a BMI value onto the standard WHO category names."""
    if bmi < 18.5:
        return "underweight"
    if bmi < 25.0:
        return "normal weight"
    if bmi < 30.0:
        return "overweight"
    return "obese"


def weight_for_bmi(bmi, height_m):
    """Return the weight in kg that gives this BMI at the given height."""
    height = _positive(height_m, "height_m")
    return round(bmi * _area(height), 1)


def healthy_weight_range(height_m):
    """Return the (min, max) weight in kg giving a normal BMI at this height."""
    lower = weight_for_bmi(18.5, height_m)
    upper = weight_for_bmi(24.9, height_m)
    return lower, upper


def weight_delta_to_normal(weight_kg, height_m):
    """Kilograms to lose (positive) or gain (negative) to reach a normal BMI."""
    lower, upper = healthy_weight_range(height_m)
    weight = _positive(weight_kg, "weight_kg")
    if weight < lower:
        return round(weight - lower, 1)
    if weight > upper:
        return round(weight - upper, 1)
    return 0.0


def describe(name, weight_kg, height_m):
    """Build a one-line report for a single person."""
    bmi = calculate_bmi(weight_kg, height_m)
    lower, upper = healthy_weight_range(height_m)
    delta = weight_delta_to_normal(weight_kg, height_m)
    line = "{:<8} BMI {:>6.2f}  {:<14} healthy range {}-{} kg".format(
        name, bmi, classify_bmi(bmi), lower, upper)
    if delta > 0:
        return line + "  (lose {:.1f} kg)".format(delta)
    if delta < 0:
        return line + "  (gain {:.1f} kg)".format(-delta)
    return line


def mean_bmi(people):
    """Return the average BMI of (name, weight_kg, height_m) records."""
    values = [calculate_bmi(weight, height) for _, weight, height in people]
    return sum(values) / len(values)


def main():
    people = [
        ("Ada", 70, 1.75),
        ("Ben", 90, 1.80),
        ("Cleo", 48, 1.68),
        ("Dan", 105, 1.72),
    ]
    for name, weight, height in people:
        print(describe(name, weight, height))
    average = mean_bmi(people)
    print("group average BMI: {:.2f} ({})".format(average, classify_bmi(average)))


if __name__ == "__main__":
    main()

