def longest_common_prefix(strings):
    if not strings:
        return ""

    prefix = strings[0]
    i = 1
    while i < len(strings):
        s = strings[i]
        while not s.startswith(prefix):
            prefix = prefix[:-1]
            if not prefix:
                return ""
        i += 1
    return prefix

