import os
import sys


def append_to_file(filepath, content):
    """Append content to filepath, returning True on success."""
    if not isinstance(filepath, str):
        return False
    if not isinstance(content, str):
        return False
    trimmed = filepath.strip()
    if trimmed == '':
        return False
    try:
        with open(filepath, 'a', encoding='utf-8') as handle:
            handle.write(content)
    except OSError:
        return False
    return True


def append_lines(filepath, lines):
    """Append each line (newline-terminated) and report how many succeeded."""
    done = []
    for line in lines:
        suffix = '' if line.endswith('\n') else '\n'
        if append_to_file(filepath, line + suffix):
            done.append(line)
        else:
            break
    return len(done)


def file_size(filepath):
    """Return the file size in bytes, or -1 if it cannot be measured."""
    try:
        return os.path.getsize(filepath)
    except OSError:
        return -1


def format_report(filepath, requested, written):
    """Build a one-line summary of an append run."""
    size = file_size(filepath)
    if written == requested:
        status = 'ok'
    else:
        status = 'failed'
    if size < 0:
        size_text = 'unknown'
    else:
        size_text = '{0} bytes'.format(size)
    return '{0}: {1}/{2} lines appended ({3}, {4})'.format(
        filepath, written, requested, status, size_text)


def main(argv):
    if len(argv) > 1:
        target = argv[1]
    else:
        target = 'test.txt'
    messages = ['Hello', 'second line', 'third line']
    requested = len(messages)
    written = append_lines(target, messages)
    print(format_report(target, requested, written))

    bad_path = os.path.join(os.sep, 'nonexistent', 'path', 'file.txt')
    if append_to_file(bad_path, 'Data'):
        print('unexpected success writing to ' + bad_path)
        return 1
    print(bad_path + ': rejected as expected')
    if written == requested:
        return 0
    return 2


if __name__ == '__main__':
    sys.exit(main(sys.argv))

