def convert_base(number, base):
    if not (2 <= base <= 16):
        raise ValueError("Base must be between 2 and 16.")
    if number == 0:
        return "0"

    digits = "0123456789ABCDEF"
    result = ""
    is_negative = False

    if number < 0:
        is_negative = True
        number = -number

    while number > 0:
        remainder = number % base
        result = digits[remainder] + result
        number = number // base

    if is_negative:
        result = "-" + result

    return result

