def rotate_list(lst, n):
    if not lst:
        return []

    list_len = len(lst)

    if list_len == 0:
        return []

    actual_shift = n % list_len

    if actual_shift == 0:
        return list(lst)

    if actual_shift > 0:
        split_point = list_len - actual_shift
        rotated_list = lst[split_point:] + lst[:split_point]
    else: # actual_shift < 0
        split_point = -actual_shift
        rotated_list = lst[split_point:] + lst[:split_point]

    return rotated_list

