import re


def count_substring_occurrences_ci(main_string, sub_string):
    """Count non-overlapping, case-insensitive occurrences of sub_string."""
    if not isinstance(main_string, str):
        raise TypeError("main_string must be a str")
    if not isinstance(sub_string, str):
        raise TypeError("sub_string must be a str")
    if sub_string == "":
        raise ValueError("sub_string must not be empty")
    haystack = main_string.lower()
    needle = sub_string.lower()
    return haystack.count(needle)


def find_occurrence_positions(main_string, sub_string):
    """Return the start offset of every case-insensitive match, left to right."""
    pattern = re.escape(sub_string)
    matches = re.finditer(pattern, main_string, re.IGNORECASE)
    return [match.start() for match in matches]


def matched_length(main_string, sub_string):
    """Number of characters of main_string that belong to a match."""
    hits = count_substring_occurrences_ci(main_string, sub_string)
    return hits * len(sub_string)


def coverage_ratio(main_string, sub_string):
    """Fraction of main_string covered by matches of sub_string."""
    total = len(main_string)
    if total == 0:
        return 0.0
    return matched_length(main_string, sub_string) / total


def format_report(main_string, sub_string):
    """Build a one-line human readable summary of the search."""
    hits = count_substring_occurrences_ci(main_string, sub_string)
    positions = find_occurrence_positions(main_string, sub_string)
    ratio = coverage_ratio(main_string, sub_string)
    if hits == 1:
        label = "match"
    else:
        label = "matches"
    where = ", ".join(str(position) for position in positions)
    if where == "":
        where = "none"
    return "{0!r} in {1!r}: {2} {3} at [{4}] covering {5:.1%}".format(
        sub_string, main_string, hits, label, where, ratio
    )


def main():
    samples = [
        ("Hello world, World wide web", "world"),
        ("Python is Fun", "fun"),
        ("aaaa", "aa"),
        ("Mississippi", "SS"),
        ("nothing here", "zebra"),
    ]
    grand_total = 0
    for main_string, sub_string in samples:
        print(format_report(main_string, sub_string))
        grand_total += count_substring_occurrences_ci(main_string, sub_string)
    print("total matches = {0} across {1} samples".format(grand_total, len(samples)))


if __name__ == "__main__":
    main()

