import string


def normalize_text(text):
    """Lowercase the text and replace punctuation with spaces."""
    if not isinstance(text, str):
        raise TypeError("text must be a string")
    cleaned = []
    for char in text.lower():
        if char in string.punctuation:
            cleaned.append(" ")
        else:
            cleaned.append(char)
    return "".join(cleaned)


def calculate_word_frequency(text):
    """Return a dict mapping each lowercase word to its number of occurrences."""
    frequency = {}
    for word in normalize_text(text).split():
        frequency.setdefault(word, 0)
        frequency[word] += 1
    return frequency


def rank_key(item):
    """Order entries by descending count, then alphabetically."""
    count = item[1]
    return (-count, item[0])


def most_common_words(frequency, limit=3):
    """Return the most frequent (word, count) pairs, at most limit of them."""
    if limit < 0:
        raise ValueError("limit must be non-negative")
    ordered = sorted(frequency.items(), key=rank_key)
    return ordered[:limit]


def unique_ratio(frequency):
    """Fraction of distinct words among all counted words."""
    total = sum(frequency.values())
    if total == 0:
        return 0.0
    return len(frequency) / total


def format_report(text, limit=3):
    """Build a human readable summary of the word statistics of text."""
    frequency = calculate_word_frequency(text)
    total = sum(frequency.values())
    percent = unique_ratio(frequency)
    lines = ["Words counted: {}".format(total)]
    lines.append("Distinct words: {}".format(len(frequency)))
    lines.append("Unique ratio: {:.1%}".format(percent))
    for rank, (word, count) in enumerate(most_common_words(frequency, limit), 1):
        lines.append("{}. {} -> {}".format(rank, word, count))
    return "\n".join(lines)


def main():
    samples = [
        "Hello world, hello Python.",
        "A quick brown fox.",
        "The rain in SPAIN stays -- mainly! -- in the plain; the rain.",
    ]
    for index, sample in enumerate(samples, 1):
        header = "Sample {}".format(index)
        print(header)
        print(calculate_word_frequency(sample))
        print(format_report(sample))
        print("-" * len(header))


if __name__ == "__main__":
    main()

